from figures import fig1, fig2, fig3, fig4, C1, C2, C3, CG

TITLE = '從經典研究方法提煉資料探勘——消費者異質性感知的數位行銷研究方法論'

def build(d, refs):
    d.title(TITLE)
    # =====================================================================================
    d.h1('壹、研究計畫之背景及目的')
    d.h2('一、研究計畫之背景')
    d.p('數位行銷正處於「資料豐富」的時代：品牌每天累積大量的瀏覽、互動、交易與影音內容資料，行銷研究的核心問題也從「這個策略平均而言是否有效」，轉向「這個策略對誰有效、在什麼情境下有效」(Wedel & Kannan, 2016)。在消費端，擴增實境（augmented reality, AR）虛擬試穿、短影音與社群商務已成為三種最具代表性的前沿互動型態：AR 讓消費者在購買前於自己的身體或空間中「試用」商品 (Javornik, 2016; Hilken et al., 2017)，並被證實能提高零售銷售 (Tan et al., 2022)；短影音以音樂、剪輯與視覺節奏在數秒內爭取注意力 (Zhao & Wagner, 2023)；社群商務則讓購買決策由同儕推薦與網紅內容所驅動 (Liang & Turban, 2011; Hajli, 2015)。')
    d.p('**然而，這三種互動型態有一個共同特性：同一項行銷刺激，對不同消費者的作用可能截然不同。**同樣的 AR 試穿，有人用來確認合身、降低買錯的風險，有人則享受「試穿」本身的樂趣 (Dacko, 2017; Barhorst et al., 2021)；同樣的快節奏短影音，可能讓一部分觀眾沉浸其中，卻讓另一部分觀眾感到資訊過載 (Lang et al., 1999; Sweller, 1988)；同樣一則好友推薦，在跨境購物的不確定情境下，其信任價值也可能大不相同 (Han & Lai, 2025)。若研究只報告平均效果，這些「消費者異質性」便會被平均值掩蓋，而實務上最需要的分群與定向決策也就缺乏依據。')
    d.p('行銷研究長期仰賴三種經典方法回答消費者行為問題：方法目的鏈（means-end chain, MEC）的階梯訪談、實驗設計與結構方程模式（structural equation modeling, SEM）。**這三種方法在面對消費者異質性時各有盲點**：MEC 受限於小樣本、人工編碼與主觀的截斷值 (Reynolds & Gutman, 1988; Grunert & Grunert, 1995)；實驗設計多只報告平均處理效果，且常僅使用單一刺激物 (Wells & Windschitl, 1999)；SEM 則假設母群同質，調節變數必須事先指定 (Hahn et al., 2002; Brandmaier et al., 2013)。另一方面，資料探勘與機器學習已發展出可解釋的異質性分析工具，包括關聯規則 (Agrawal et al., 1993)、因果森林 (Wager & Athey, 2018) 與 SEM 決策樹 (Brandmaier et al., 2013)，大型語言模型（large language models, LLMs）也開始被用於行銷研究的資料蒐集與編碼 (Li et al., 2024; Arora et al., 2025)。但若把資料探勘直接套用在資料上，很容易因為候選變數多、演算法彈性大，而「找到」並不存在的族群差異 (Simmons et al., 2011)。')
    d.p('**「經典方法」與「資料探勘」不應是二選一的關係。**經典方法的長處在於理論與推論：MEC 讓研究者理解消費者「為什麼」重視某項屬性，實驗設計讓研究者確認因果，SEM 讓研究者檢驗理論所預期的心理路徑 (Anderson & Gerbing, 1988)。資料探勘的長處則在於規模與彈性：它能處理大量文字與影音資料，也能在不預設族群的情況下找出效果的差異 (Berger et al., 2020; Wager & Athey, 2018)。若只用經典方法，研究者只能檢驗事先想到的調節變數；若只用資料探勘，研究者得到的族群往往缺乏理論解釋，也難以確認是否只是樣本中的偶然。兩者結合，才能同時回答「為什麼」與「對誰」。')
    d.p('因此，本計畫以**「保留經典方法、嵌入資料探勘核心、以預先註冊與保留樣本驗證」**為核心問題意識，發展一套「消費者異質性感知」的數位行銷研究方法論。本計畫不預設要比較哪些消費者族群，也不為單一產品客製研究參數，而是讓族群由資料發現、再以獨立樣本確認。研究以運動鞋為錨定案例，美妝保養與居家家具為複製品類，三者都有成熟的 AR 試穿或擺放應用，且品類內同時有享樂型與實用型產品 (Dhar & Wertenbroch, 2000)，用以證明方法可跨品類推廣。本計畫採「發現 → 檢驗 → 推廣」三階段設計，分二年進行，各階段的核心問題如下。')

    d.h4('第一階段：消費者為什麼使用 AR 試穿？價值結構的大規模探索')
    d.q('消費者在使用 AR 虛擬試穿時，內心最深層的價值結構為何？這些「屬性－後果－價值」結構可分為哪些價值族群？能否以大型語言模型將階梯訪談擴大到數百人，而不犧牲效度？')
    d.p('第一階段是本計畫的發現階段。AR 試穿的價值不只在於功能，而在於它如何連結到消費者的個人價值：即時 3D 成像可能帶來「確認合身」的後果，進而連結到「避免社交尷尬」或「自信」等終極價值 (Gutman, 1982; Reynolds & Gutman, 1988)。虛擬試穿可降低網購的不確定感 (Kim & Forsythe, 2008; Plotkina & Saurel, 2019)，而退貨是服飾電商的主要成本來源 (de Leeuw et al., 2016)，因此 AR 試穿的價值結構，直接關係到降低感知風險與退貨率的實務問題。')
    d.p('然而，傳統階梯訪談通常只有數十位受訪者，難以據以分群。本階段保留 MEC 理論與軟式階梯訪談，但以大型語言模型主持對話式訪談 (Xiao et al., 2020)，將樣本擴大到約 600 人，並以關聯規則探勘取代主觀截斷值，把每一條階梯視為一筆「交易紀錄」，建構可檢驗穩定性的階梯價值圖。本階段沿用量化 MEC 分群的思路 (Ter Hofstede et al., 1998, 1999)，找出共享特定價值主幹的「價值族群」，作為後續兩階段的候選調節變數。')
    d.p('本階段以消費價值理論與方法目的鏈理論為理論基礎。消費價值理論指出，消費選擇是功能、社會、情感、知識與情境等多元價值的函數 (Sheth et al., 1991)；方法目的鏈則說明這些價值如何經由具體屬性與使用後果被實現 (Gutman, 1982)。以本研究而言，前者提供價值的「類型」，後者提供價值的「路徑」，兩者結合可說明同一項 AR 功能為何對不同消費者具有不同意義；感知風險理論 (Dowling & Staelin, 1994) 則把價值結構連結到購買、退貨與後悔等可觀察的行為後果。')

    d.h4('第二階段：短影音的視聽一致性對誰有效？異質處理效果的實驗檢驗')
    d.q('音樂節奏與剪輯頻率的一致性，是否能降低認知負荷、提高品牌記憶與觀看意願？這個效果在哪些消費者身上特別強、在哪些消費者身上消失？')
    d.p('第二階段是本計畫的檢驗階段。感官線索會影響消費者的知覺與判斷 (Krishna, 2012)，音樂與廣告畫面的契合程度會影響廣告效果 (Oakes, 2007; Bruner, 1990)，而資訊越容易處理，評價越正向 (Reber et al., 2004)。根據有限容量模型，剪輯節奏與喚起內容共同決定觀眾的注意與記憶 (Lang et al., 1999; Lang, 2000)。品牌貼文的視覺一致性已被證實會透過心流與美感提高行銷成效 (Luarn et al., 2024)，但「視聽」一致性在短影音中是否有效、對誰有效，仍缺乏因果證據。')
    d.p('本階段以 2×2×2 受試者間實驗操弄音樂喚起、剪輯頻率與產品類型，並在三個品類中以多個刺激物複製 (Wells & Windschitl, 1999)；再合併約 1,440 位受試者與側寫變數，以因果森林估計每位受試者的條件效果 (Wager & Athey, 2018; Athey et al., 2019)，找出效果特別強或消失的「反應族群」，交由第三階段驗證。')
    d.p('本階段採用有限容量模型與處理流暢度理論為脈絡。有限容量模型說明，觀眾處理影音訊息的資源有限，結構特徵與內容特徵共同決定資源的分配 (Lang, 2000)；處理流暢度理論則說明，容易處理的刺激會帶來較正向的評價 (Reber et al., 2004)。以本研究而言，音樂與剪輯一致的影片被預期能降低處理成本、提高流暢度，進而提高品牌記憶與觀看意願；而消費者既有的處理能力與動機（如認知需求、短影音使用經驗、價值傾向）不同，正是一致性效果可能因人而異的理論原因。')

    d.h4('第三階段：社群推薦何時、對誰促成購買？異質性路徑模型的推廣驗證')
    d.q('在社群商務中，好友與網紅的推薦如何透過信任與資訊診斷性影響購買轉換？跨境購物的不確定性是否放大強連結的信任價值？這條路徑在哪些消費者身上成立、在哪些身上失效？')
    d.p('第三階段是本計畫的推廣階段。強連結（真實朋友）提供信任，弱連結（網紅）則提供新資訊與觸及 (Granovetter, 1973; Brown & Reingen, 1987)；微型與巨型網紅的外溢效果也不相同 (Ji et al., 2025)。跨境購買的運送較久、退貨較難、心理距離較遠 (Han & Lai, 2025)，消費者面對較高的不確定性，理論上會放大強連結的信任價值 (Morgan & Hunt, 1994; Gefen et al., 2003)。')
    d.p('本階段先以傳統 SEM 估計「關係強度 → 信任／診斷性 → 態度 → 購買轉換」的基準模型 (Anderson & Gerbing, 1988)，再以 SEM 決策樹、SEM 森林與潛在類別 SEM 找出模型在哪些消費者身上成立 (Brandmaier et al., 2013, 2016; Hahn et al., 2002)，並以樣本外預測比較單一群體與異質性模型 (Shmueli et al., 2019)。前兩階段發現的價值族群與反應族群，在本階段成為預先註冊的驗證假設，形成「前一階段的發現是後一階段的假設」之理論引導資料探勘。')
    d.p('本階段採用社會資本與關係強度理論、信任理論與心理距離為脈絡。社會資本理論把人際關係視為可轉化為價值的資源 (Nahapiet & Ghoshal, 1998)，關係強度理論說明強、弱連結分別提供信任與新資訊 (Granovetter, 1973)；信任理論說明信任是降低交易不確定性、促成承諾與購買的核心機制 (Morgan & Hunt, 1994)。以本研究而言，推薦來源的關係強度被視為刺激，信任與資訊診斷性為中介的心理狀態，產品態度與購買轉換為最終反應；跨境賣家的心理距離則是放大或縮小強連結價值的情境條件。')

    d.p('三個階段並非各自獨立的研究，而是以「族群」為線索串連的研究管線：第一階段找出的價值族群，在第二階段成為因果森林的候選變數；第二階段找出的反應族群，在第三階段成為預先註冊的驗證假設；三個階段又共用同一份側寫問卷與品類庫，使族群可以在不同方法、不同資料之間被重複檢驗。換言之，**本計畫的主角是方法論本身**，AR 試穿、短影音與社群商務則是檢驗此方法論能否跨情境推廣的三個試驗場。')
    d.h4('研究缺口')
    d.p('首先，既有數位行銷研究多以單一品類、單一方法、平均效果回答問題。例如心流在 VR、TikTok 與 Instagram 情境的研究 (Fang & Chung, 2025; Zhao & Wagner, 2023; Luarn et al., 2024)，以及 AR 試穿對品牌反應的研究 (Smink et al., 2019; Rauschnabel et al., 2019)，都未檢驗效果在哪些消費者身上不成立。**當研究只回答「平均而言是否有效」，便無法回應實務上「對誰有效」的問題，此為本研究可介入探討的第一缺口。**')
    d.p('其次，MEC 已有量化分群的前例 (Ter Hofstede et al., 1998, 1999)，大型語言模型在行銷研究的效度也開始受到檢驗 (Li et al., 2024; Arora et al., 2025)，但兩者尚未被整合為一套可大規模執行、以人工訪談為基準的階梯法；因果機器學習 (Wager & Athey, 2018) 與 SEM 決策樹 (Brandmaier et al., 2013) 也很少用於數位行銷。**經典方法與資料探勘之間缺乏系統性的整合程序，此為本研究可介入探討的第二缺口。**')
    d.p('最後，資料探勘找到的族群差異，若未經預先註冊與獨立樣本確認，極易成為偽陽性結果 (Simmons et al., 2011; Nosek et al., 2018)；而族群定義若涉及性別、年齡等特徵，用於定向行銷時也有公平性與隱私風險 (Martin & Murphy, 2017)。**現有研究缺乏一套「發現、驗證、公平」兼顧的異質性研究程序，此為本研究可介入探討的第三缺口。**有鑑於此，本研究以「從經典研究方法提煉資料探勘」為核心問題意識，規劃二年三階段的研究計畫。')

    d.h4('研究計劃各階段問題與目的')
    d.p('本計畫研究架構共分為三個部分，分二年三個階段進行。第一階段（2027.08–2028.07，追蹤調查延至 2029.01）採質化為主、量化為輔的方式，以「計算化階梯法」探索 AR 虛擬試穿在三個品類中的「屬性－後果－價值」結構，並找出價值族群。接著，第二階段（2027.11–2029.04）延續第一階段的價值傾向，以短影音語料庫的觀察資料與 2×2×2 跨品類實驗，檢驗視聽一致性的因果效果，並以因果森林找出反應族群。')
    d.p('第三階段（2028.02–2029.07）則將前兩階段的發現轉為預先註冊的驗證假設，以情境實驗與真實購物回憶調查，建構社群商務的異質性路徑模型。三個階段使研究脈絡由第一年的「價值發現」、第二年的「因果檢驗」推進至「模型推廣」，並共用同一份消費者側寫問卷、品類庫與異質性驗證程序，形成一套完整且遞進的研究邏輯。')

    d.h4('研究計劃各階段主題與層次脈絡')
    d.p('本計畫將於第二年完成研究，綜整三個階段的結果，比較個別方法在解釋上的獨特性，並驗證三種方法整合後的一致性，最後轉譯為中小企業可用的分群與內容測試工具。關於二年三階段研究計畫之主題、層次脈絡、研究方法與理論基礎，整理如表 1。')
    d.table('表 1　二年三階段研究計畫層次脈絡、研究問題、主題、研究方法及研究理論列表',
            [1300, 700, 1900, 1850, 1900, 1988],
            [['研究階段\n與時程', '層次\n脈絡', '研究問題', '主題', '研究方法\n（資料探勘核心）', '研究理論基礎'],
             [dict(t='第一階段\n2027.08–2028.07\n（追蹤至 2029.01）', c=True), dict(t='初步\n發現', c=True), '消費者為什麼使用 AR 試穿？價值結構的大規模探索', 'AR 虛擬試穿在降低感知風險與退貨率之作用：計算化階梯法', 'MEC 軟式階梯訪談\n（LLM 對話式訪談與輔助編碼、關聯規則、網絡分析、階梯分群）', 'MEC 理論\n消費價值理論\n感知風險理論'],
             [dict(t='第二階段\n2027.11–2029.04', c=True), dict(t='深入\n檢驗', c=True), '短影音的視聽一致性對誰有效？', '短影音行銷中的情緒喚起與視聽一致性：誰最受影響', '2×2×2 實驗設計\n（影片探勘、跨品類刺激抽樣、因果森林）', '有限容量模型\n處理流暢度理論\n認知負荷理論'],
             [dict(t='第三階段\n2028.02–2029.07', c=True), dict(t='推廣\n驗證', c=True), '社群推薦何時、對誰促成購買？', '社群商務中的同儕動態與去中心化購買：異質性 SEM', 'SEM\n（SEM 決策樹與森林、潛在類別 SEM、樣本外預測）', '社會資本與關係強度理論\n信任理論\n心理距離']],
            center_cols=(1,))
    d.p('**本計畫透過此三階段、跨方法、跨品類的整合研究設計，回應數位行銷「從平均效果走向異質效果」的關鍵議題。**對於經典研究方法如何吸收資料探勘的長處，又不失理論與推論的嚴謹性，本計畫提出一個可複製的方向，有助於學術社群、品牌、電商平台與中小企業在進行消費者分群與內容測試時，兼顧效度與公平性。')

    d.h2('二、研究計畫之目的')
    d.p('本研究規劃整體研究架構，以系統性的思維考量各階段的從屬性及關聯性。**本研究旨在建立一套「經典方法 × 資料探勘」的消費者異質性研究方法論，並以 AR 試穿、短影音與社群商務三個前沿情境加以驗證。**首先，以計算化階梯法大規模探索 AR 試穿的價值結構，檢驗大型語言模型訪談與編碼的效度，並找出跨品類共通與品類特定的價值族群。其次，以跨品類實驗與因果森林檢驗短影音視聽一致性的因果效果，並描繪「對誰有效」的異質處理效果地圖。最後，以 SEM 決策樹與潛在類別 SEM 驗證社群商務路徑模型的邊界條件，並將三階段的分析程序整合為開源工具包與中小企業使用指南。')

    d.h2('三、研究計畫之原創性、重要性與預期影響性')
    d.h3('(一) 本研究之原創性方面：')
    d.p('本研究之原創性在「研究方法」、「理論整合」與「研究程序」三個層面。首先，相較既有文獻將資料探勘視為取代經典方法的工具，本研究**保留 MEC、實驗與 SEM 的理論與推論邏輯，在每種方法中嵌入可解釋的資料探勘核心**，提出「計算化階梯法」、「實驗 × 因果森林」與「SEM × SEM 決策樹」三種整合方法。其次，本研究整合 MEC 理論、有限容量模型、處理流暢度與社會資本理論，以「前一階段的發現是後一階段的假設」串連三個研究，形成理論引導的資料探勘。第三，在研究程序上，本計畫以預先註冊、發現／確認樣本切分、安慰劑變數、置換檢定、拔靴穩定性與偽發現率控制，建立一套可供後續研究沿用的異質性驗證程序 (Nosek et al., 2018; Benjamini & Hochberg, 1995)。')
    d.h3('(二) 本研究之重要性、預期影響性方面：')
    d.p('本研究之重要性，學術上，補足數位行銷研究對「異質效果」與「方法整合」缺乏系統性探討的缺口，三個階段各自形成可投稿頂級期刊的方法與理論貢獻；實務上，研究結果可協助品牌判斷 AR 試穿、短影音與社群推薦「對誰有效」，降低無效投放與退貨成本。本研究之預期影響性，在學術層面，預期建立可複製的異質性研究程序；在實務層面，提供資源受限的中小企業低成本的分群與內容測試工具 (Wang & Zhang, 2025)；在社會層面，以降低退貨減少逆向物流的碳足跡，並建立個資與演算法公平的研究指引 (Martin & Murphy, 2017)。本計畫與五大研究主題之對應如表 2。')
    d.table('表 2　本計畫與五大研究主題之對應',
            [2400, 1700, 5538],
            [['研究主題', '在計畫中的角色', '對應內容'],
             ['主題一　創新發展', dict(t='研究情境', c=True), 'AR 虛擬試穿、短影音、社群商務三種前沿互動型態'],
             ['主題二　消費者心理行為', dict(t='依變數與中介機制', c=True), '終極價值、感知風險、情緒喚起、認知負荷、信任'],
             ['主題三　電子商務模式', dict(t='商業結果', c=True), '去中心化的社群購買、完播與轉換、退貨機制'],
             ['主題四　研究潛力', dict(t='方法論核心', c=True), 'AI 演算法、精準定向（異質性發現）與歸因（因果推論）的整合'],
             ['主題五　電商市場發展需求', dict(t='實務轉譯', c=True), '中小企業可用的開源分群工具、個資與演算法公平指引、降低退貨的永續效益']])

    # =====================================================================================
    d.h2('四、國內外相關之文獻探討')
    d.h4('第一部分【初步發現】AR 虛擬試穿之消費者價值內涵探索：從人工階梯訪談至計算化階梯法')
    d.p('第一階段研究以方法目的鏈探索 AR 虛擬試穿的消費者價值內涵，並以大型語言模型與關聯規則將階梯法擴大為可分群的大樣本方法。本階段採用方法目的鏈理論、消費價值理論與感知風險理論為理論基礎，以下就相關文獻分述之。')
    d.h3('（一）AR 虛擬試穿與感知風險')
    d.p('AR 虛擬試穿係以手機鏡頭將 3D 商品疊加在消費者的身體或空間中，讓消費者在購買前「試用」商品 (Javornik, 2016; Hilken et al., 2017)，涵蓋試鞋 (Song et al., 2022)、試妝與家具擺放。AR 購物應用同時提供實用與享樂利益 (Dacko, 2017)，其互動性與生動性可提高購買意圖 (Yim et al., 2017)，AR 帶來的靈感也能改善品牌態度 (Rauschnabel et al., 2019)；在零售實務上，AR 已被證實能提高銷售 (Tan et al., 2022)。電腦中介環境中的心流概念 (Hoffman & Novak, 1996) 也延伸到 AR 與沉浸式購物 (Barhorst et al., 2021; Sharma et al., 2026)，但亦可能產生認知偏誤等負面影響 (Ghosh et al., 2025)。')
    d.p('三個品類的 AR 形式並不相同：運動鞋的 AR 是把鞋子疊加在腳上，核心問題是尺寸與外觀是否合適 (Song et al., 2022)；美妝的 AR 是在臉上試妝，核心問題是色號與膚色是否相配；居家家具的 AR 則是把商品擺放在自己的空間中，核心問題是尺寸、風格與空間是否協調 (Hilken et al., 2017)。同樣是「在自己身上或空間中試用」，三個品類所降低的風險類型不同，可能連結到的價值也不同。這正是本研究以跨品類設計區分「共通價值結構」與「品類特定價值結構」的理由。')
    d.p('感知風險是消費者在購買前對可能損失的主觀預期，當感知風險超過可接受水準時，消費者會積極採取降低風險的行動 (Dowling & Staelin, 1994)。虛擬試穿正是一種降低網購不確定感的工具 (Kim & Forsythe, 2008; Plotkina & Saurel, 2019)，並可能影響個資揭露意願 (Smink et al., 2019)。退貨是服飾電商的主要成本來源 (de Leeuw et al., 2016)，各種退貨預防工具的效果已有實證比較 (Walsh & Möhring, 2017)，寬鬆的退貨政策則會同時影響退貨傾向與滿意度 (Duong et al., 2025)；AR 服務的合作機制設計也需要在退貨、定價與顧客滿意之間取得平衡 (Z. Li et al., 2025)。然而，**消費者究竟「為什麼」使用 AR 試穿、這些理由如何連結到個人價值，以及不同消費者是否有不同的價值路徑，仍缺乏系統性的探索。**')
    d.h3('（二）消費價值理論')
    d.p('消費價值理論（theory of consumption values）主張，消費選擇是多元消費價值的函數，可分為功能性、社會性、情感性、知識性與情境性五種價值，且各價值在不同情境中的相對貢獻不同 (Sheth et al., 1991)。此理論提供了一個理解 AR 試穿價值的框架：確認尺寸與合身屬於功能價值；試穿的樂趣屬於情感價值 (Holbrook & Hirschman, 1982)；在社群上分享試穿畫面屬於社會價值；嘗試新科技屬於知識價值；而在無法到店的情境下使用 AR，則屬於情境價值。同一項 AR 功能，對不同消費者可能對應到不同的價值類型，這正是本研究以價值族群描述異質性的理論基礎。')
    d.h3('（三）方法目的鏈理論與階梯法')
    d.p('方法目的鏈認為，消費者行為是目標導向的，產品的具體屬性（attributes, A）透過使用後的後果（consequences, C），最終連結到個人的終極價值（values, V），形成「屬性－後果－價值」的認知結構 (Gutman, 1982)。階梯法（laddering）是 MEC 最常用的資料蒐集方法，以一對一深度訪談，反覆追問「這對你為什麼重要」，引導受訪者由具體屬性逐步上升到抽象價值 (Reynolds & Gutman, 1988)。MEC 亦可用於描述消費者的目標結構，並揭露消費者的涉入程度 (Pieters et al., 1995)。')
    d.p('傳統階梯法有三個方法限制。其一，訪談成本高，樣本通常僅數十人；其二，A/C/V 的編碼依賴人工判斷，信度需另外檢驗 (Kassarjian, 1977; Perreault & Leigh, 1989)；其三，階梯價值圖（hierarchical value map, HVM）以主觀的截斷值決定保留哪些連結，結果隨截斷值改變 (Grunert & Grunert, 1995)。Ter Hofstede et al. (1998) 以關聯模式技術量化 MEC，並進一步以消費者與產品的關係進行國際市場分群 (Ter Hofstede et al., 1999)，證明 MEC 可以結合量化分群。')
    d.h3('（四）價值族群與量化方法目的鏈')
    d.p('方法目的鏈的分析單位傳統上是「整體樣本的階梯價值圖」，但不同消費者往往經由不同的路徑抵達不同的價值。Ter Hofstede et al. (1998) 提出關聯模式技術，以結構化問卷量化屬性－後果與後果－價值的連結，使 MEC 可以進行統計分析；Ter Hofstede et al. (1999) 進一步以消費者與產品之間的「方法目的」關係進行國際市場分群，發現分群結果比以人口或地理變數分群更能預測消費者反應。這兩項研究說明，以價值結構描述消費者異質性在方法上是可行的。')
    d.p('然而，關聯模式技術以事先列出的屬性與價值清單為前提，失去了軟式階梯法「由受訪者自己說出理由」的優點。本研究的設計是：仍以開放式的軟式階梯訪談蒐集資料，再以大型語言模型輔助編碼，把開放式回答轉為可分析的 A–C–V 連結向量，最後以潛在類別分群找出價值族群。如此，價值族群既保留了質化資料的豐富性，又具備量化分群的可重現性；族群的穩定性與重現性，則以第貳部分所述的發現／確認樣本程序加以檢驗。')
    d.h3('（五）大型語言模型、對話式訪談與關聯規則')
    d.p('AI 聊天機器人已被用於以開放式問題進行對話式調查，並能引出品質較高的回答 (Xiao et al., 2020)。在行銷研究中，大型語言模型可作為研究者的協作者 (Arora et al., 2025)，其自動化知覺分析的效度也已有系統性的檢驗 (Li et al., 2024)；文字探勘則為行銷洞察提供了成熟的方法基礎 (Berger et al., 2020)。然而，生成式 AI 可能帶有偏誤，需以公平性指標與去偏程序加以檢查 (Wei et al., 2025)。關聯規則探勘以支持度、信賴度與提升度找出項目之間的共現規則 (Agrawal et al., 1993)，若把每條階梯視為一筆交易紀錄，即可用客觀門檻取代主觀截斷值，並以拔靴法檢驗階梯價值圖的穩定性。')
    d.p('以大型語言模型主持階梯訪談有三項潛在優勢：其一，可同時進行數百場訪談，突破人力限制；其二，追問規則一致，可降低不同訪談員之間的差異；其三，受訪者面對 AI 時可能較願意談論某些敏感的理由，例如身材焦慮或購買失敗的經驗。但也有三項風險：模型可能過早結束追問、以誘導性語句影響回答，或在編碼時將模稜兩可的回答歸入較常見的類別。因此，本研究不假定大型語言模型訪談與真人訪談等效，而是把「等效性」本身作為研究問題，以同一批受訪者的真人與機器人訪談比較兩者引出的階梯，並以人工編碼為基準檢驗自動編碼的一致性。')
    d.p('綜合而言，**以大型語言模型擴大階梯訪談規模、以關聯規則建構階梯價值圖，並以人工訪談為基準檢驗其等效性，是目前文獻尚未建立的研究程序。**因此，第一階段提出以下研究問題：')
    d.hyp('RQ1：大型語言模型主持的階梯訪談，引出的階梯是否與真人訪談等效？自動編碼是否與人工編碼一致？')
    d.hyp('RQ2：以關聯規則建構的階梯價值圖，是否比傳統截斷值法更穩定、更能預測行為？')
    d.hyp('RQ3：AR 試穿的「屬性－後果－價值」結構可分為哪些價值族群？哪些結構跨品類共通、哪些屬於特定品類？')
    d.hyp('RQ4：價值族群能否在人口變數之外，預測後續的 AR 使用與退貨行為？')
    d.p('**小結。**既有 AR 研究多以問卷或實驗檢驗 AR 對購買意圖與品牌態度的平均效果，較少回到消費者「為什麼」使用 AR 的價值層次；MEC 研究雖能回答「為什麼」，卻受限於小樣本而難以分群。本研究第一階段以計算化階梯法同時保留兩者的優點，並以人工訪談為基準檢驗新方法的效度，從此一缺口介入探討。')

    d.h4('第二部分【深入檢驗】短影音行銷中的情緒喚起與視聽一致性：誰最受影響')
    d.p('第二階段延續第一階段的價值傾向，聚焦於短影音的「視聽一致性」，以跨品類實驗檢驗其因果效果，並以因果森林找出反應族群。本階段採用有限容量模型、處理流暢度與認知負荷理論為理論基礎，以下就相關文獻分述之。')
    d.h3('（一）有限容量模型與認知負荷')
    d.p('有限容量模型主張，觀眾處理媒介訊息的認知資源有限，訊息的結構特徵（如剪輯節奏）與內容特徵（如情緒喚起）共同決定資源的分配，進而影響注意與記憶 (Lang, 2000)。實證研究發現，剪輯節奏與喚起內容對資訊處理有交互作用：適度的快節奏可提高注意，但與高喚起內容結合時可能造成負荷過重 (Lang et al., 1999)。認知負荷理論亦指出，當外在負荷過高，學習與記憶的表現會下降 (Sweller, 1988)，而主觀心智努力是衡量認知負荷的有效指標 (Paas, 1992)。TikTok 的研究也顯示，影片長度與使用經驗會調節使用者的心流經驗 (Zhao & Wagner, 2023)。')
    d.h3('（二）跨感官一致性與處理流暢度')
    d.p('感官行銷指出，感官線索會影響消費者的知覺、判斷與行為 (Krishna, 2012)。音樂會影響情緒與廣告反應 (Bruner, 1990)，而音樂與廣告其他元素的契合程度，是解釋音樂效果的關鍵 (Oakes, 2007)。處理流暢度理論認為，刺激越容易處理，觀眾的美感與評價越正向 (Reber et al., 2004)。近年研究從多模態評論 (Sun et al., 2025)、AR 情境的模態一致與干擾 (Kaur et al., 2025)，到注意力焦點對多感官一致性的神經證據 (Ramírez-Benítez et al., 2025)，都支持「一致性降低處理成本」的觀點。據此，本研究將「音樂節奏」與「剪輯頻率」相互契合的影片界定為視聽一致，並提出以下假說：')
    d.p('在短影音情境中，一致性的意義尤其重要。短影音以直式畫面、自動播放與滑動切換為特徵，觀眾可在一秒內決定是否離開；影片若在最初幾秒造成處理困難，觀眾便可能直接滑走，品牌資訊也無從被編碼進記憶。因此，本研究同時以「認知負荷」衡量處理成本，以「處理流暢度」衡量處理的主觀容易程度，並以「停留秒數」與「是否看完」作為行為指標，以觀察一致性是否同時影響心理歷程與實際觀看行為。')
    d.hyp('H1：一致組（快節奏＋高頻切換、慢節奏＋慢速運鏡）的認知負荷低於不一致組。')
    d.hyp('H2：音樂喚起 × 剪輯頻率對品牌記憶有交互作用，一致組的品牌記憶較佳。')
    d.hyp('H3：視聽一致性透過處理流暢度，提高品牌記憶與觀看意願。')
    d.h3('（三）產品類型的調節')
    d.p('享樂型產品著重感官愉悅與情感經驗，實用型產品著重功能與工具性目標 (Holbrook & Hirschman, 1982; Dhar & Wertenbroch, 2000)；消費者對產品的態度也可分為享樂與實用兩個面向 (Batra & Ahtola, 1991; Voss et al., 2003)。廣告訴求與產品類型的配對會影響購買意圖 (Zhang et al., 2025)。據此推論，享樂型產品與高喚起的一致組合較匹配，實用型產品則與低喚起的一致組合較匹配：')
    d.p('本研究在每個品類中各選一組享樂型與實用型產品：運動鞋為潮流聯名鞋與機能跑鞋、美妝保養為彩妝與防曬機能保養、居家家具為裝飾燈具與人體工學椅。如此，產品類型的比較是在品類「內」進行，可排除品類本身的差異；而三個品類的複製，則可檢驗產品類型的調節作用是否跨品類一致。')
    d.hyp('H4：產品類型調節一致性效果：享樂型產品以高喚起一致組最佳，實用型產品以低喚起一致組最佳；此模式跨品類成立。')
    d.h3('（四）情緒喚起、品牌記憶與刺激抽樣')
    d.p('情緒反應可由愉悅、喚起與支配三個向度描述，自我評量人形圖（self-assessment manikin, SAM）以圖示讓受試者快速評估情緒，且與語意差異量表高度相關 (Bradley & Lang, 1994)。在廣告研究中，喚起會影響注意力的分配與記憶的編碼：適度的喚起可提高注意，但過高的喚起若伴隨快速剪輯，可能使觀眾來不及處理品牌資訊 (Lang et al., 1999; Lang, 2000)。因此，本研究以立即與三天後的自由回憶及再認，區分短期注意與較穩定的記憶編碼。')
    d.p('此外，行銷實驗常以單一刺激物代表一個實驗條件，使研究結果可能只反映該刺激物的特性，而非理論所關心的變數。刺激抽樣主張每個條件應以多個刺激例子呈現，並在分析中把刺激視為隨機因子，才能將結果推廣到刺激之外 (Wells & Windschitl, 1999)。本研究在三個品類中各以多支影片與多個產品例子呈現同一條件，正是為了回應此一問題，並使「此模式跨品類成立」成為可檢驗的假說。')
    d.h3('（五）異質處理效果與因果森林')
    d.p('同一實驗操弄對不同消費者的效果大小，稱為異質處理效果。遞迴切分可在保留推論效度的前提下估計異質效果 (Athey & Imbens, 2016)，因果森林則以「誠實」切分估計個別條件效果並提供信賴區間 (Wager & Athey, 2018)，廣義隨機森林進一步提供一般化的估計架構 (Athey et al., 2019)。影片探勘可自動擷取視覺資訊 (Li et al., 2019)，音訊分析工具可擷取節奏與能量 (McFee et al., 2015)，以影像與文字特徵預測網紅行銷成效的研究亦已出現 (Hsiao & Lin, 2025)。相較於傳統以交互作用項檢驗事先指定的調節變數，因果森林的優點是不需預設哪些變數會造成差異，而能同時考慮數十個側寫變數；其限制則是結果可能過度擬合樣本，因此必須搭配誠實切分、保留樣本與偽陽性防護。據此，本研究提出探索性假說：')
    d.hyp('H5（探索性，預先註冊程序）：視聽一致性的效果在消費者之間存在異質性，且可由側寫變數與第一階段的價值傾向解釋。')
    d.p('**小結。**跨感官一致性與處理流暢度的文獻多以靜態廣告或電視廣告為情境，且多報告平均效果；短影音的研究則多聚焦於心流與使用意願，較少以控制實驗檢驗音樂與剪輯的一致性。本研究第二階段以跨品類、多刺激物的實驗確認因果效果，再以因果森林回答「對誰有效」，從此一缺口介入探討。')

    d.h4('第三部分【推廣驗證】社群商務中的同儕動態與去中心化購買：異質性 SEM')
    d.p('第三階段將前兩階段的發現轉為預先註冊的驗證假設，以社群商務的推薦情境建構異質性路徑模型。本階段採用社會資本與關係強度理論、信任理論與心理距離為理論基礎，以下就相關文獻分述之。')
    d.h3('（一）社群商務、關係強度與信任')
    d.p('社群商務是以社群互動與使用者內容支持交易的電商形式，核心在於「發現與分享」 (Liang & Turban, 2011)，社群商務構面會透過信任提高購買意圖 (Hajli, 2015)。社會資本理論指出，社會網絡中的關係是可轉化為價值的資源 (Nahapiet & Ghoshal, 1998; Qiao & Qiu, 2024)。關係強度理論區分強連結與弱連結：弱連結帶來新資訊與觸及 (Granovetter, 1973)，強連結在口碑推薦中則較常被尋求、影響也較大 (Brown & Reingen, 1987)。信任是關係行銷的核心 (Morgan & Hunt, 1994)，在網路購物中的重要性與知覺有用性相當 (Gefen et al., 2003)；社群商務的信任網絡與評論資訊亦會影響購買決策 (Wu et al., 2022; Zhao & Yu, 2022)。據此提出：')
    d.p('就信任的來源而言，強連結推薦者與受試者之間有長期互動的歷史，受試者較能判斷推薦者的動機是否出於善意；弱連結的網紅推薦則常伴隨業配或分潤，受試者較容易啟動說服知識，懷疑推薦背後的商業動機。社群商務中的信任也會沿著社會網絡傳遞，好友的信任可部分轉移到其推薦的商品與賣家 (Wu et al., 2022; X. Li et al., 2025)。因此，本研究預期：')
    d.hyp('H1：強連結推薦比弱連結推薦帶來較高的感知信任。')
    d.h3('（二）網紅推薦、資訊診斷性與產品類型')
    d.p('網紅的專業性、可信度與吸引力是代言效果的來源 (Ohanian, 1990)，網紅的印象管理會透過信任轉移影響直播購買 (X. Li et al., 2025)，微型與巨型網紅的外溢效果亦不相同 (Ji et al., 2025)。資訊診斷性是指一項資訊對判斷的幫助程度，可及性與診斷性共同決定資訊是否被用於判斷 (Feldman & Lynch, 1988)。享樂型產品的評價較依賴主觀體驗與人際信任，實用型產品則較依賴專業資訊 (Dhar & Wertenbroch, 2000)。據此提出：')
    d.hyp('H2：關係強度 × 產品類型有交互作用：享樂型產品下強連結的優勢較大，實用型產品下網紅的專業形象可縮小差距。')
    d.hyp('H3：感知信任與資訊診斷性中介關係強度對產品態度與購買轉換的影響。')
    d.p('產品態度與購買意圖是行銷研究中最常見的結果變數：消費者對產品的整體評價包含享樂與實用兩個面向 (Batra & Ahtola, 1991)，而知覺品質與知覺價值會影響購買意願 (Dodds et al., 1991)。然而，自陳的購買意圖與實際行為之間常有落差，測量行為本身也可能改變受試者的信念與意圖 (Feldman & Lynch, 1988)。因此，本研究在態度與意圖之外，另以「是否加入購物車」作為行為層次的購買轉換指標。')
    d.h3('（三）跨境購物的心理距離')
    d.p('跨境電商的消費者面對較長的運送時間、較困難的退貨與較遠的心理距離，數位原生世代則能部分降低此一距離 (Han & Lai, 2025)。當不確定性升高，消費者更依賴可信賴的資訊來源以降低風險 (Dowling & Staelin, 1994)。因此，賣家來源（國內 vs. 跨境）可能放大強連結推薦的信任價值，而跨國購物經驗越豐富者，對跨境不確定性的敏感度越低。據此提出：')
    d.hyp('H4：關係強度 × 賣家來源有交互作用：跨境賣家情境下，強連結推薦對信任的優勢較大。')
    d.hyp('H5：跨國購物經驗調節 H4：經驗越豐富，跨境情境對強連結優勢的放大效果越弱。')
    d.h3('（四）異質性 SEM')
    d.p('SEM 決策樹以側寫變數遞迴切分樣本，找出使模型參數改變的變數 (Brandmaier et al., 2013)，SEM 森林則以多棵樹評估變數重要性，實現理論引導的探索 (Brandmaier et al., 2016)；有限混合 PLS 可找出無法由觀察變數界定的潛在族群 (Hahn et al., 2002)。族群比較前需檢驗測量恆等性 (Cheung & Rensvold, 2002; Henseler et al., 2016)，模型的預測力則應以樣本外預測評估 (Shmueli et al., 2019)。')
    d.p('傳統的多群組 SEM 只能比較研究者事先指定的群組，例如男性與女性；若真正造成路徑差異的是「跨國購物經驗 × 品類涉入」的組合，事先指定的分組便無法發現。SEM 決策樹的做法是：在每一個節點上，以概似比檢定比較「不分群」與「依某一變數切分」的模型，選出使模型參數改變最大的切分，並遞迴進行，最後得到一棵以側寫變數描述的族群樹 (Brandmaier et al., 2013)。此方法與第二階段的因果森林形成互補：因果森林處理單一處理效果的異質性，SEM 決策樹則處理整條心理路徑的異質性。此外，實驗資料具備因果推論力但情境較人工，回憶調查具備生態效度但屬相關性資料，本研究以兩種資料交叉驗證，以兼顧內部與外部效度。據此，本研究提出：')
    d.hyp('H6（預先註冊驗證）：第二階段因果森林找出的反應族群，在本階段的路徑模型中亦呈現差異。')
    d.hyp('H7（探索性）：SEM 決策樹與潛在類別 SEM 找出的族群，其樣本外預測力優於單一群體模型；回憶調查的結果與實驗結果一致。')
    d.p('**小結。**社群商務與網紅行銷的研究已確認信任的核心角色，但多以單一群體模型估計路徑，調節變數也多由研究者事先指定；跨境電商的研究則多從平台或物流角度出發，較少檢驗跨境不確定性如何改變社群推薦的效果。本研究第三階段以異質性 SEM 讓資料決定模型的邊界條件，並以前兩階段的族群作為預先註冊的驗證假設，從此一缺口介入探討。')

    # =====================================================================================
    d.h1('貳、研究方法、進行步驟及執行進度')
    d.h2('一、研究架構與研究假說')
    d.h3('（一）二年研究計畫架構圖')
    d.p('本計畫研究架構共分為三個部分，分二年三個階段進行。本計畫以「方法論層次」為縱軸、「時間構面」為橫軸：由第一階段的價值發現出發，逐步加入實驗操弄與因果機器學習，再推廣到路徑模型與其邊界條件，藉以觀察消費者在三種前沿互動情境中的心理與行為差異。三個階段共用消費者側寫問卷、品類庫與異質性驗證程序，最後轉譯為中小企業可用的工具。二年三階段研究計畫之架構概略圖如圖 1。')
    d.figure(fig1(), '圖 1　二年研究計畫架構概略圖')
    d.p('**方法論共同基礎。**所有受訪者與受試者填寫同一份約 10 分鐘的消費者側寫問卷，作為異質性發現的候選變數，而非事先指定的調節變數，內容包括：人口變數；心理特質，如五大人格簡版 (Gosling et al., 2003)、認知需求 (Cacioppo et al., 1984) 與品類涉入 (Zaichkowsky, 1985)；數位行為，如網購頻率、AR 與短影音使用經驗、跨國購物與退貨經驗。不納入星座、血型等缺乏科學預測效度的變數。品類抽樣框架為：運動鞋（潮流聯名鞋 vs. 機能跑鞋，錨定案例、最大樣本）、美妝保養（彩妝 vs. 防曬機能保養）、居家家具（裝飾燈具 vs. 人體工學椅）。運動鞋情境已有 Adidas Originals (Luarn et al., 2024)、客製化鞋款 (Canarslan & Bariş, 2021)、Nike (Xin et al., 2025; W. Li et al., 2025) 與球鞋文化 (Matthews et al., 2021) 等研究可供參照。實驗刺激物一律使用虛構品牌，品類在分析中視為隨機因子 (Wells & Windschitl, 1999)。')

    d.h3('（二）第一階段研究架構概念呈現：【初步發現】AR 虛擬試穿之消費者價值內涵探索：計算化階梯法')
    d.p('第一階段以方法目的鏈對 AR 虛擬試穿的使用者進行價值內涵探索（屬性、後果及價值），並以「人工訪談基準」與「大型語言模型訪談」雙路徑蒐集資料。')
    d.item('1. 主要框架：以「AR 虛擬試穿（三品類）」為主題做 MEC（屬性 → 後果 → 價值），使萃取的屬性、後果與價值具跨品類代表性。')
    d.item('2. 在每一組屬性的追問中，系統性詢問「試穿後的購買、退貨與後悔」相關後果，把風險降低與退貨行為放入後果層級，以連結 RQ4 的預測效度。')
    d.item('3. 把「訪談者（真人 vs. 大型語言模型）」視為方法屬性加以比較：同一批受訪者以順序平衡接受兩種訪談，以檢驗 RQ1 的等效性。訪談的開放式問題架構見表 3。')
    d.table('表 3　第一階段依據屬性、後果及價值之訪談開放式問題架構',
            [1700, 7938],
            [['層級', '開放式問題'],
             [dict(t='Attributes\n屬性', c=True, b=True), '1. 您使用 AR 試穿時，哪一個功能或畫面最吸引您、讓您覺得「有用」？\n2. 和在實體店試穿或只看商品照片相比，AR 試穿有哪些不同？\n3. 在運動鞋、彩妝或家具三種商品中，您最在意的 AR 功能是否相同？'],
             [dict(t='Consequences\n後果', c=True, b=True), '1. 剛剛提到的這些功能，為您帶來什麼樣的感受或結果？\n2. 使用 AR 試穿後，您對買錯尺寸、顏色不合或退貨的擔心有沒有改變？\n3. 試穿之後，您會立刻購買、暫時觀望，還是放棄購買？為什麼？'],
             [dict(t='Values\n價值', c=True, b=True), '1. 這樣的結果對您個人而言，最重要的意義是什麼？\n2. 如果 AR 試穿讓您「買對了」，這代表您是一個什麼樣的人？\n3. 若 AR 試穿的結果和實際收到的商品不同，會影響您重視的哪些事情？'],
             [dict(t='訪談者比較\n（真人 vs. AI）', c=True, b=True), '1. 剛才和 AI 訪談者（或真人訪談者）對話時，您覺得哪一種讓您說得比較完整？\n2. 有沒有哪些想法，您比較願意告訴 AI、或比較願意告訴真人？'],
             [dict(t='結尾\n價值驗證', c=True, b=True), '1. 您認為哪些 AR 功能最會促使您真正購買或推薦給朋友？\n2. 如果用一句話說明您對 AR 試穿的期待，您會怎麼說？']])
    d.p('**本計畫尚未進行正式訪談。**為使編碼簿有明確起點，本計畫依據前述文獻預擬 AR 試穿的初始屬性、後果與價值要素（表 4）。研究 1a 的人工訪談將以此為基礎進行開放編碼，新增、合併或刪除要素，產出正式編碼簿後，再供研究 1c 的大型語言模型輔助編碼使用。')
    d.table('表 4　依文獻預擬之 AR 試穿屬性、後果及價值各層級要素（初始編碼簿）',
            [3212, 3213, 3213],
            [['屬性（A）', '後果（C）', '價值（V）'],
             ['A01 即時 3D 成像 (Javornik, 2016)', 'C01 確認合身與尺寸 (Kim & Forsythe, 2008)', 'V01 自信'],
             ['A02 互動與生動性 (Yim et al., 2017)', 'C02 降低買錯風險 (Dowling & Staelin, 1994)', 'V02 避免社交尷尬'],
             ['A03 在自己身上／空間中試用 (Hilken et al., 2017)', 'C03 減少退貨與後悔 (Walsh & Möhring, 2017)', 'V03 安全感'],
             ['A04 多款式快速切換', 'C04 試穿的樂趣與心流 (Barhorst et al., 2021)', 'V04 自我表現'],
             ['A05 拍照與社群分享', 'C05 節省時間與到店成本', 'V05 精明消費（不浪費）'],
             ['A06 個資與影像授權 (Smink et al., 2019)', 'C06 獲得穿搭或擺設靈感 (Rauschnabel et al., 2019)', 'V06 環境責任感（減少退貨運輸）'],
             [dict(t='註：要素依 Gutman (1982) 的三層級定義預擬，正式要素以研究 1a 的訪談與編碼結果為準。', span=3)]])

    d.h3('（三）第二階段研究架構圖：【深入檢驗】短影音視聽一致性與異質處理效果：實驗設計 × 因果森林')
    d.p('第二階段延續第一階段的價值傾向，以音樂喚起、剪輯頻率與產品類型三個操弄變數，檢驗視聽一致性透過認知負荷與處理流暢度，對品牌記憶與觀看意願的影響，並以因果森林檢驗效果的異質性，如圖 2 所示。')
    d.figure(fig2(), '圖 2　第二階段研究架構圖')
    d.h5('【假說】')
    for h in ['H1：一致組的認知負荷低於不一致組',
              'H2：音樂喚起 × 剪輯頻率對品牌記憶有交互作用，一致組記憶較佳',
              'H3：一致性透過處理流暢度提高品牌記憶與觀看意願',
              'H4：產品類型調節一致性效果：享樂型以高喚起一致最佳，實用型以低喚起一致最佳；此模式跨品類成立',
              'H5（探索性）：一致性效果在消費者之間存在異質性，且可由側寫變數與第一階段的價值傾向解釋']:
        d.hyp(h)

    d.h3('（四）第三階段研究架構圖：【推廣驗證】社群商務異質路徑模型：SEM × SEM 決策樹')
    d.p('第三階段以 2（推薦來源：強連結 vs. 弱連結）× 2（產品類型：享樂型 vs. 實用型）× 2（賣家來源：國內 vs. 跨境）情境實驗，並測量跨國購物經驗，建構「關係強度 → 信任／診斷性 → 態度 → 購買轉換」的路徑模型；再以 SEM 決策樹與潛在類別 SEM 檢驗模型的邊界條件，如圖 3。')
    d.figure(fig3(), '圖 3　第三階段研究架構圖')
    d.h5('【假說】')
    for h in ['H1：強連結推薦比弱連結推薦帶來較高的感知信任',
              'H2：關係強度 × 產品類型有交互作用：享樂型產品下強連結優勢較大',
              'H3：感知信任與資訊診斷性中介關係強度對產品態度與購買轉換的影響',
              'H4：關係強度 × 賣家來源有交互作用：跨境賣家情境下強連結的信任優勢較大',
              'H5：跨國購物經驗越豐富，跨境情境對強連結優勢的放大效果越弱',
              'H6（預先註冊驗證）：第二階段的反應族群在本階段路徑模型中亦呈現差異',
              'H7（探索性）：異質性模型的樣本外預測力優於單一群體模型']:
        d.hyp(h)

    # =====================================================================================
    d.h2('二、研究方法、實驗設計、問卷設計與變數操作型定義')
    d.h3('（一）第一階段【AR 虛擬試穿之消費者價值內涵探索：計算化階梯法】：執行時間 2027.08–2028.07（追蹤至 2029.01）')
    d.p('第一階段以方法目的鏈為基礎架構，先以人工軟式階梯訪談建立基準，再以大型語言模型擴大訪談規模；以內容分析法與大型語言模型輔助編碼形成受訪者階梯，以關聯規則與涵意矩陣描繪要素間的關係，最後建構階梯價值圖並進行價值分群。')
    d.h5('1. 階梯訪談法與訪談對象')
    d.p('階梯法可分為軟式與硬式兩種：硬式階梯法限制受訪者逐層回答，軟式階梯法則讓受訪者自由回答，能獲得較豐富的個人脈絡 (Grunert & Grunert, 1995)。本研究以軟式階梯訪談為基準方法，分為兩個研究：')
    d.item('(1) 研究 1a：人工軟式階梯（基準，2027.08–2028.01）。立意抽樣 48 位過去 12 個月內曾以 AR 試穿後購買者（運動鞋 24、美妝 12、家具 12），男女各半，由受過訓練的訪談員進行，每次約 50–60 分鐘。產出編碼簿與傳統截斷值階梯價值圖，作為後續比較基準。')
    d.item('(2) 研究 1b：大型語言模型對話式階梯訪談（2027.11–2028.04）。以大型語言模型建置訪談機器人，依 Reynolds & Gutman (1988) 的追問規則逐層追問。線上樣本約 600 人（運動鞋 300、美妝 150、家具 150），全部填寫消費者側寫問卷。另有約 40 人同時接受真人與機器人訪談（順序平衡），以等效性檢定比較兩者引出的階梯數、層級深度與要素分布。')
    d.h5('2. 訪談題目')
    d.p('第一階段訪談題目的層級、目的與探問脈絡如表 5。訪談前向受訪者說明研究目的、資料保密方式與訪談時間，並事先告知機器人訪談者為 AI；訪談中以不打斷受訪者為原則，接續其回答向上追問，直到受訪者無法再說明為止。')
    d.table('表 5　方法目的鏈訪談題目：AR 虛擬試穿（含真人／AI 訪談者與跨品類探問）',
            [1250, 1500, 2550, 2238, 2100],
            [['層級', '訪談目的', '核心訪談題目（主問題）', '延伸探問（深入原因）', '跨品類／訪談者比較探問'],
             [dict(t='A 層級\n屬性', c=True, b=True), '了解受訪者對 AR 試穿可感知特徵的認知（畫面、互動、資訊）',
              '1.「您用過的 AR 試穿中，哪些功能最讓您印象深刻？」\n2.「一個好的 AR 試穿，應該具備哪些元素？」',
              '- 為什麼這個功能吸引您？\n- 哪些功能讓您開始懷疑試穿結果？', '- 換成其他品類（鞋、彩妝、家具），最在意的功能會改變嗎？'],
             [dict(t='C 層級\n後果', c=True, b=True), '探索屬性帶來的功能性或心理後果（風險、樂趣、決策）',
              '3.「這些功能帶給您哪些感受或結果？」\n4.「試穿後，您對買錯或退貨的擔心有什麼改變？」\n5.「試穿如何影響您最後買或不買？」',
              '- 它讓您更確定合身嗎？\n- 有沒有因此少退一次貨？\n- 試穿本身好玩嗎？', '- 在哪一個品類中，AR 最能降低您的擔心？為什麼？'],
             [dict(t='V 層級\n價值', c=True, b=True), '探索 AR 試穿觸及的深層個人價值（自信、安全、自我表現、責任）',
              '6.「這些結果對您個人最重要的意義是什麼？」\n7.「回想一次滿意的 AR 購物，是哪些價值促使您這麼做？」',
              '- 這與您的生活信念有關嗎？\n- 這是為了自己，還是在意別人的眼光？', '- 不同品類觸動的價值相同嗎？'],
             [dict(t='收尾題', c=True, b=True), '整合訪談者經驗、購買與退貨連結', dict(t='8.「和 AI（或真人）訪談者對話時，您覺得哪一種讓您說得比較完整？」\n9.「以上談到的因素，哪些最可能影響您未來使用 AR 試穿與退貨？」\n10.「如果用一句話說明您對 AR 試穿的期望，您會怎麼說？」', span=3)]])
    d.h5('3. 訪談程序')
    d.p('訪談程序分為四步：(1) 篩選：以篩選題確認受訪者過去 12 個月內曾使用 AR 試穿並完成購買，並以品類涉入量表 (Zaichkowsky, 1985) 排除涉入極低者，以強化資料品質；(2) 情境喚起：請受訪者回想最近一次使用 AR 試穿的經驗，必要時以手機重新操作一次；(3) 階梯追問：依表 5 由屬性層級開始，每個屬性以「這對您為什麼重要」向上追問，直到受訪者無法再說明為止；(4) 收尾：詢問訪談者比較題與基本資料。研究 1b 的機器人訪談採相同流程，追問規則以提示詞固定，並設定每條階梯至少追問三層、至多六層，避免過早結束或無限追問。')
    d.h5('4. 資料分析方法')
    d.p('**(1) 內容分析與大型語言模型輔助編碼（研究 1c，2028.02–2028.04）。**內容分析法可將訪談資料客觀、系統化地分類 (Kassarjian, 1977)。本研究先以研究 1a 的訪談建立編碼簿：由兩位編碼員獨立編碼，依要素的「源引」與「延至」關係判定其屬於 A、C 或 V 層級，並以 Cohen 的 kappa (Cohen, 1960) 與 Perreault & Leigh (1989) 的信度指標檢驗一致性。接著以編碼簿引導大型語言模型編碼研究 1b 的全部階梯，再抽 20% 樣本由兩位人工編碼員獨立編碼，以 kappa 與 F1 值評估人機一致性。編碼規則不綁定特定模型：記錄模型版本、參數與提示詞，並以一個開源權重模型與一個商用模型平行編碼，檢驗結果對模型更替的穩健性，同時依 Wei et al. (2025) 的建議檢查編碼是否因受訪者的性別或年齡而產生系統性偏誤。')
    d.p('**(2) 涵意矩陣與關聯規則階梯價值圖（研究 1d，2028.05–2028.07）。**傳統做法以涵意矩陣計算要素之間的直接與間接連結次數，再以截斷值繪製階梯價值圖 (Reynolds & Gutman, 1988; Pieters et al., 1995)。本研究同時保留此一做法作為比較基準，並將每條階梯視為一筆交易紀錄，以關聯規則（支持度、信賴度、提升度門檻事先註冊，例如支持度 ≥ 5%、信賴度 ≥ 30%、提升度 > 1.2）建構階梯價值圖 (Agrawal et al., 1993)；以拔靴法比較兩種方法的穩定性，並以網絡分析（中心性、社群偵測）找出核心價值。')
    d.p('**(3) 價值分群與預測效度（研究 1d、1e）。**以受訪者的 A–C–V 連結向量進行潛在類別分群（2–6 類，以 BIC 選擇），沿用量化 MEC 分群的思路 (Ter Hofstede et al., 1998, 1999)，再以深度 ≤ 3 的決策樹將價值族群連結到側寫變數。研究 1e（2028.08–2029.01）請研究 1b 的受訪者於 3 個月後填寫追蹤問卷，回報 AR 使用、購買、退貨或購後後悔，以檢驗價值族群在人口變數之外的增量預測力（RQ4）。此外，亦以性別、年齡與品類比較各族群的價值結構，以獲得更完整的脈絡解讀。')
    d.h5('5. 預計分析脈絡')
    d.p('第一階段預計於 12 個月內完成主要分析，追蹤調查延至第二年上半年。分析脈絡由三個層次展開：首先，以人工與機器人訪談的等效性及人機編碼一致性，回答方法層次的問題（RQ1）；其次，比較關聯規則與截斷值兩種階梯價值圖的穩定性與預測力（RQ2）；最後，以價值族群回答實質層次的問題，包括哪些價值結構跨品類共通、哪些屬於特定品類，以及族群能否預測後續的 AR 使用與退貨（RQ3、RQ4）。價值族群經確認樣本驗證後，轉為第二、三階段側寫問卷中的價值傾向題組。')

    d.h3('（二）第二階段【短影音視聽一致性與異質處理效果：實驗設計】：執行時間 2027.11–2029.04')
    d.h5('1. 與前一階段之銜接與連貫性')
    d.p('第一階段以計算化階梯法找出 AR 試穿的價值族群，這些族群在本階段轉為側寫問卷中的「價值傾向」題組，成為因果森林的候選變數。第一階段回答「消費者重視什麼」，本階段則以控制實驗回答「一項行銷操弄的效果對誰不同」，使研究由描述性的價值結構推進到因果推論。')
    d.h5('2. 研究設計與實驗分組')
    d.item('(1) 研究 2a：短影音影片探勘（觀察資料，2027.11–2028.07）。以平台開放的研究 API 或公開資料集，建立三個品類約 1,500 支商品短影音的語料庫；以 librosa 擷取音樂節奏與能量 (McFee et al., 2015)，以鏡頭邊界偵測計算剪輯頻率，並參考影片探勘方法擷取視覺特徵 (Li et al., 2019)；再以可解釋模型分析「節奏－剪輯一致指標」與公開互動指標（以粉絲數標準化）的關係，提供生態效度，並說明為何需要實驗確認因果。')
    d.item('(2) 研究 2b：錨定實驗——運動鞋（2028.05–2028.07 前測；2028.08–2028.10 正式）。虛構品牌的潮流聯名鞋與機能跑鞋各製作 4 支 15 秒直式影片，共 8 支，在模擬手機短影音滑動介面中播放，記錄停留秒數與是否看完。N = 480（每格 60 人）。')
    d.item('(3) 研究 2c：跨品類複製——美妝與家具（2028.08–2029.01）。兩個品類各自套用相同設計，每種產品類型各使用 2 個產品例子以進行刺激抽樣 (Wells & Windschitl, 1999)；N ≈ 960（每品類 480）。分析以混合模型將品類與產品例子視為隨機效果。')
    d.item('(4) 研究 2d：異質處理效果（2028.11–2029.04）。合併研究 2b、2c（N ≈ 1,440）與側寫變數，以因果森林（2,000 棵樹、誠實切分、以刺激影片為聚類單位）估計一致性對每位受試者的條件效果 (Wager & Athey, 2018; Athey & Imbens, 2016)，再以深度 ≤ 2 的決策樹將高、低效果者描述為可解釋的反應族群，結果交由第三階段驗證。')
    d.p('樣本數方面，三因子交互作用以 f = 0.15、α = .05、檢定力 .80 估算 (Faul et al., 2007)，每品類需約 350 人，預留 30% 淘汰後每品類 480 人；合併後的 1,440 人亦滿足保留 30% 確認樣本的需求。')
    d.h5('3. 刺激物製作與實驗步驟')
    d.p('刺激物以研究 2a 語料庫中節奏與剪輯頻率的實際分布為藍圖，並參考第一階段的價值語彙撰寫字卡文案。每個品類的享樂型與實用型產品各拍攝同一組素材，再依 2×2 組合配上不同節奏的音樂與剪輯版本，使四個版本的畫面內容、資訊量與長度相同，只有音樂與剪輯不同，以控制其他變因。前測（每品類約 40 人）檢驗音樂喚起、剪輯速度與產品類型三個操弄是否成立，並依結果微調音樂與剪輯參數。正式實驗依下列步驟進行：')
    d.item('第一步驟：受試者由線上樣本供應商的連結進入實驗網站，閱讀知情同意說明後按下「開始」。')
    d.item('第二步驟：篩選題詢問「過去一個月是否觀看過短影音平台」與「是否有網路購物經驗」，兩者皆為「是」者進入下一步，否則結束實驗。')
    d.item('第三步驟：填寫約 10 分鐘的消費者側寫問卷，包含第一階段產出的價值傾向題組。')
    d.item('第四步驟：隨機分派至 8 格之一，在模擬手機的直式滑動介面中瀏覽 6 支影片，其中第 3 支為目標影片、其餘為填充影片；系統記錄每支影片的停留秒數與是否看完。')
    d.item('第五步驟：填答認知負荷、SAM、處理流暢度、品牌態度與操弄檢驗題項，並完成立即回憶與再認測驗；3 天後以電子郵件邀請完成延遲記憶測驗，最後說明實驗目的。')
    d.h5('4. 變數操作型定義及衡量')
    d.table('表 6　第二階段實驗變數操作型定義與衡量方式',
            [1500, 3300, 3238, 1600],
            [['研究變數', '操作型定義', '操弄／衡量方式', '參考出處'],
             [dict(t='音樂喚起', b=True), '背景音樂的節奏速度與情緒喚起程度', '快節奏高喚起（BPM 較高、能量較強）vs. 慢節奏低喚起；以 librosa 量測並經前測確認', 'Bruner (1990)\nMcFee et al. (2015)'],
             [dict(t='剪輯頻率', b=True), '影片中每秒鏡頭切換的次數', '高頻切換 vs. 慢速運鏡；「快＋高頻」與「慢＋慢速」為一致組', 'Lang et al. (1999)\nOakes (2007)'],
             [dict(t='產品類型', b=True), '產品主要提供享樂或實用利益', '每品類各一組享樂型與實用型產品；以 HED/UT 量表做操弄檢驗', 'Dhar & Wertenbroch (2000)\nVoss et al. (2003)'],
             [dict(t='認知負荷', b=True), '觀看影片時投入的心智努力', '九點心智努力量表（1 = 非常非常低，9 = 非常非常高）', 'Paas (1992)'],
             [dict(t='情緒喚起與愉悅', b=True), '觀看影片後的情緒狀態', '自我評量人形圖（SAM）九點量表', 'Bradley & Lang (1994)'],
             [dict(t='處理流暢度', b=True), '理解與處理影片內容的容易程度', '「這支影片很容易看懂」「畫面與音樂很協調」「我不費力就能跟上內容」（Likert 七點）', 'Reber et al. (2004)'],
             [dict(t='品牌記憶', b=True), '觀看後對品牌與產品資訊的記憶', '立即與 3 天後的自由回憶及再認正確率', 'Lang (2000)'],
             [dict(t='品牌態度與觀看意願', b=True), '對品牌的整體評價與繼續觀看的傾向', '語意差異量表；停留秒數、是否看完（行為資料）', 'Batra & Ahtola (1991)\nZhao & Wagner (2023)']])
    d.h5('5. 資料分析方法')
    d.p('本階段的分析分為四步：(1) 操弄檢驗：以 t 檢定確認音樂喚起、剪輯速度與產品類型的操弄成立，未通過注意力檢核者依預先註冊的排除規則剔除。(2) 主要效果與交互作用：以線性混合模型檢驗 H1、H2 與 H4，固定效果為三個操弄變數及其交互作用，隨機效果為品類、產品例子與刺激影片，使結論可推廣到刺激之外 (Wells & Windschitl, 1999)。(3) 中介效果：依 Zhao et al. (2010) 的建議，以拔靴法檢驗處理流暢度的間接效果（H3），並區分互補型、競爭型與僅間接中介。(4) 異質處理效果：以因果森林估計條件效果，先以校準檢定確認森林能區分高、低效果者，再以變數重要性與深度 ≤ 2 的決策樹描述反應族群，最後依共同的發現／確認樣本程序驗證（H5）。研究 2a 的觀察資料則以可解釋模型分析一致指標與互動指標的關係，作為實驗結果的生態效度對照。')

    d.h3('（三）第三階段【社群商務異質路徑模型：結構方程模式】：執行時間 2028.02–2029.07')
    d.h5('1. 與前一階段之銜接與連貫性')
    d.p('第二階段以因果森林找出視聽一致性的反應族群，並描繪「對誰有效」的異質處理效果地圖。然而，實驗回答的是單一操弄的因果效果，尚未說明消費者從接觸推薦到購買的完整心理路徑，也尚未檢驗前兩階段的族群在不同情境中是否仍然成立。因此，第三階段以 SEM 建構路徑模型，並把第一階段的價值族群與第二階段的反應族群寫入預先註冊的驗證假設（H6），使三階段的發現得到第三份獨立資料的檢驗。')
    d.h5('2. 研究設計')
    d.item('(1) 研究 3a：錨定情境實驗——運動鞋（2028.11–2029.01）。台灣線上樣本 N = 640（每格 80 人），跨國購物經驗高、低各半，各層內隨機分派至 8 格。強連結組以受試者自填的好友暱稱呈現推薦貼文，弱連結組呈現虛構網紅帳號；賣家來源以商品頁上的出貨地、預計到貨時間與退貨條件呈現（國內：3 天內到貨、可退貨；跨境：海外直送、約 10–14 天、退貨需自付運費，實際條件於前測時依主要跨境平台當時的條件更新）。貼文文案依第一階段的階梯價值圖撰寫，以「加入購物車」為行為指標。')
    d.item('(2) 研究 3b：跨品類複製——美妝與家具（2028.11–2029.01）。兩品類各 N = 480（每格 60 人），共 960 人，套用相同設計。')
    d.item('(3) 研究 3c：真實購物回憶調查（2028.11–2029.01）。招募約 1,000 位過去 6 個月內曾因社群推薦而購買的台灣消費者，回想最近一次經驗，回報與推薦者的實際關係強度、產品類型、賣家是否跨境，以及信任、滿意度、退貨或後悔與再購意願。此研究提供生態效度，也為 SEM 決策樹提供大樣本；屬相關性資料，用於補強而非取代實驗的因果證據。')
    d.p('三個研究皆由台灣線上樣本供應商招募（2028.02–2028.04 向 2–3 家詢價），依性別、年齡與跨國購物經驗設配額；以 Qualtrics 施測，設注意力檢核題與最短作答時間。合計約 2,600 人，全部填寫共同的消費者側寫問卷。前測於 2028.08–2028.10 進行（約 80 人），確認三個操弄皆成立。')
    d.h5('3. 實驗步驟')
    d.p('研究 3a、3b 的實驗程序如下：(1) 受試者閱讀知情同意說明並通過篩選題（有網購經驗、使用至少一種社群媒體）；(2) 填寫側寫問卷，並回報過去 12 個月的跨國購物次數；(3) 強連結組請受試者寫下一位常聯絡好友的暱稱，該暱稱僅在瀏覽器端用於呈現推薦貼文；(4) 隨機分派至 8 格之一，瀏覽模擬社群動態中的推薦貼文，點入後看到商品頁（含出貨地、到貨時間與退貨條件），並可選擇「加入購物車」或「離開」；(5) 填答信任、診斷性、態度、購買意圖、感知風險與操弄檢驗題項；(6) 填寫基本資料，最後說明實驗目的與虛構品牌。研究 3c 則以回憶引導語請受訪者描述最近一次因社群推薦而購買的經驗，再填答相同構念的題項。')
    d.h5('4. 問卷設計與衡量問項')
    d.p('研究變數的操作型定義與預計衡量問項如表 7。問項依據過去文獻，再根據本研究情境調整，並經前測修訂；除另行說明者外，均使用 Likert 七點量表（1 = 非常不同意，7 = 非常同意）。')
    d.table('表 7　第三階段研究變數操作型定義與預計衡量問項',
            [1350, 2250, 4238, 1800],
            [['研究變數', '操作型定義', '問項', '參考出處'],
             [dict(t='關係強度\n（操弄檢驗）', b=True), '受試者與推薦者之間關係的親密程度', '1. 我和這位推薦者的關係很親近。\n2. 我經常和這位推薦者聯絡。', 'Brown & Reingen (1987)\nGranovetter (1973)'],
             [dict(t='推薦者可信度', b=True), '受試者知覺推薦者的專業性與可信程度', '1. 這位推薦者對這類商品很專業。\n2. 這位推薦者是誠實可靠的。\n3. 這位推薦者的意見值得參考。', 'Ohanian (1990)'],
             [dict(t='感知信任', b=True), '相信推薦內容與賣家會履行承諾的程度', '1. 我相信這則推薦所說的內容。\n2. 我相信這個賣家會依說明出貨。\n3. 整體而言，我對這次購物感到放心。', 'Gefen et al. (2003)\nMorgan & Hunt (1994)'],
             [dict(t='資訊診斷性', b=True), '推薦資訊對判斷商品是否適合自己的幫助程度', '1. 這則推薦幫助我判斷商品是否適合我。\n2. 看完推薦，我更清楚商品的優缺點。\n3. 這則推薦提供了做決定所需的資訊。', 'Feldman & Lynch (1988)\n（依概念自行發展，經前測檢驗）'],
             [dict(t='產品態度', b=True), '對推薦商品的整體評價', '語意差異量表：不好／好、不喜歡／喜歡、不實用／實用、無趣／有趣', 'Batra & Ahtola (1991)\nVoss et al. (2003)'],
             [dict(t='購買意圖與\n購買轉換', b=True), '購買推薦商品的傾向與實際行為', '1. 我願意購買這項商品。\n2. 我未來購買這項商品的可能性很高。\n行為指標：是否點擊「加入購物車」。', 'Dodds et al. (1991)'],
             [dict(t='感知風險', b=True), '購買可能帶來損失的主觀預期', '1. 這次購買可能讓我買到不適合的商品。\n2. 若不滿意，退貨會很麻煩。', 'Dowling & Staelin (1994)'],
             [dict(t='跨國購物經驗', b=True), '過去 12 個月在國外電商網站購物的經驗', '過去 12 個月在國外電商網站購物的次數（連續變數；招募時依高、低分層）', 'Han & Lai (2025)'],
             [dict(t='產品類型\n（操弄檢驗）', b=True), '產品主要提供享樂或實用利益', 'HED/UT 量表（享樂與實用各 5 個語意差異題項）', 'Voss et al. (2003)']])
    d.h5('5. 資料分析方法')
    d.p('研究 3d（2029.02–2029.04）的分析步驟如下：(1) 以敘述統計描述樣本結構，並以 Harman 單因子檢定與標記變數法檢查共同方法變異 (Podsakoff et al., 2003)。(2) 依兩階段法先以驗證性因素分析檢驗測量模式 (Anderson & Gerbing, 1988)，以組合信度、平均變異萃取量與區別效度檢驗信效度 (Fornell & Larcker, 1981)，並以 CFI、TLI、RMSEA、SRMR 評估適配度 (Hu & Bentler, 1999)。(3) 估計結構模式，檢驗 H1–H5；跨品類與跨研究比較前先檢驗測量恆等性 (Cheung & Rensvold, 2002)，若以 PLS-SEM 估計則以 MICOM 程序檢驗 (Henseler et al., 2016; Hair et al., 2019)。(4) 以 SEM 決策樹與 SEM 森林分析全部側寫變數、跨國購物經驗、價值族群與反應族群標記 (Brandmaier et al., 2013, 2016)，以潛在類別 SEM 比對未觀察的族群 (Hahn et al., 2002)，並在保留樣本中以 PLSpredict 等指標比較單一群體與異質性模型的樣本外預測力 (Shmueli et al., 2019)。')

    d.h3('（四）三階段共同之異質性發現與驗證程序')
    d.p('資料探勘最大的風險是找到假的族群差異：候選變數多、演算法彈性大，只要嘗試的次數夠多，總能在樣本中切出「看起來有差異」的族群 (Simmons et al., 2011)。本計畫因此把「發現」與「驗證」拆成兩個互不干擾的階段，三個階段共用表 8 的七個步驟；任何一步未通過，該族群就不得以「已確認」的結果報告。')
    d.table('表 8　異質性發現與驗證程序',
            [1900, 4000, 2300, 1438],
            [['步驟', '主要做法', '判定門檻／產出', '時點'],
             ['1 預先註冊', '在 OSF 公開演算法、候選變數、超參數範圍與判定標準 (Nosek et al., 2018)；只註冊程序，不預設會找到哪些族群', '每階段 1 份註冊文件（含時間戳記）', '2027.11–2028.01'],
             ['2 資料品質與變數準備', '套用排除規則；缺失率 ≤ 5% 者以多重插補（m = 20）處理；高度相關（|r| > .80）者擇一保留', '資料清理紀錄；候選變數 ≤ 30 個', '資料蒐集後 2 週內'],
             ['3 發現／確認樣本切分', '於品類 × 條件各層內隨機保留 30% 確認樣本；由未參與分析者執行並加密封存', '公開切分種子碼與 SHA-256 雜湊值', '資料清理完成當日'],
             ['4 發現樣本探勘', '以預先註冊的演算法探勘；超參數只在發現樣本內以 5 摺交叉驗證選定後凍結', '每個候選族群一張「族群卡」', '依各階段時程'],
             ['5 偽陽性防護', '安慰劑與影子變數、1,000 次置換檢定、500 次拔靴（出現率 ≥ 70%）(Meinshausen & Bühlmann, 2010)、Benjamini–Hochberg 偽發現率 q = .05 (Benjamini & Hochberg, 1995)', '四項檢查全部通過的族群（至多 5 個）', '確認樣本解封前'],
             ['6 確認樣本驗證', '凍結規則一次性套用；判定標準：方向一致、校正後 q < .05、效果量至少保留發現樣本的 50% (Athey & Imbens, 2016)', '「已確認／部分確認／未確認」三級判定，全數揭露', '解封後 1 個月內'],
             ['7 穩健性與透明報告', '多元宇宙分析 (Steegen et al., 2016)、逐一保留品類的跨品類重現、排除受保護特徵後的公平性檢查 (Martin & Murphy, 2017)', '完整族群卡、偏離紀錄、開源程式碼', '論文撰寫期']])
    d.p('各階段的最小族群規模設為發現樣本的 10%：第一階段（研究 1b，約 600 人）為 42 人、第二階段（研究 2b＋2c，約 1,440 人）為 100 人、第三階段實驗（研究 3a＋3b，約 1,600 人）為 112 人、回憶調查（研究 3c，約 1,000 人）為 70 人。報告時明確區分預先註冊的驗證性檢定、預先註冊程序下的探索性發現與事後分析；事後分析只作為未來研究的假設，不作結論。')

    # =====================================================================================
    d.h2('三、研究進行步驟，以及二年時程之必要性、貢獻性')
    d.p('本研究計畫規劃為二年期，是基於研究問題本身的層次性，以及方法設計由發現、檢驗到推廣之必要性所做的安排。首先，第一階段以計算化階梯法萃取 AR 試穿的價值結構與價值族群。由於價值涉及高度抽象的內在信念，且大型語言模型訪談必須先以人工訪談為基準完成效度檢驗，此一階段不宜壓縮，亦難以與量化研究同時進行；其產出的價值族群，是後兩階段側寫問卷的必要內容。')
    d.p('其次，第二階段的實驗需要先以影片語料庫了解市場上的節奏與剪輯分布，再製作三品類共 24 支以上的刺激影片並完成前測，才能進行正式實驗與因果森林分析；因果森林所需的大樣本，也必須累積三個品類的實驗資料。最後，第三階段需要以前兩階段的族群作為預先註冊假設，因此必須在第二階段的反應族群確認後才能解封驗證。三個階段環環相扣，每一年度皆具獨立且不可替代的功能，又為下一階段提供必要的理論與實證基礎。')
    d.p('綜上所述，本計畫遵循「發現 → 檢驗 → 推廣」的研究邏輯，採二年期規劃實屬研究問題本質與學術貢獻所必須。最後，將三階段結果作逐次及統合的比較、分析、整合及詮釋，並轉譯為開源工具與中小企業指南。本研究計畫之進行步驟見圖 4，各工作項目的執行進度見表 9。')
    d.figure(fig4(), '圖 4　二年三階段研究之進行步驟圖')
    q = ['Q1', 'Q2', 'Q3', 'Q4'] * 2
    G = [('共同：倫理審查、側寫問卷、預先註冊', 0, 1, CG), ('一 1a：人工階梯訪談（N = 48）', 0, 1, C1), ('一 1b：LLM 階梯訪談（N ≈ 600）', 1, 2, C1),
         ('一 1c：LLM 輔助編碼與一致性', 2, 2, C1), ('一 1d：關聯規則與價值分群', 3, 3, C1), ('一 1e：三個月追蹤', 4, 5, C1),
         ('二 2a：影片語料與特徵擷取', 1, 3, C2), ('二：三品類刺激物與前測', 2, 3, C2), ('二 2b：運動鞋實驗（N = 480）', 4, 4, C2),
         ('二 2c：美妝、家具複製', 4, 5, C2), ('二 2d：因果森林', 5, 6, C2), ('三：量表與問卷設計', 2, 3, C3), ('三：介面建置與前測', 3, 4, C3),
         ('三 3a–3c：實驗與回憶調查', 5, 5, C3), ('三 3d：SEM 樹與潛在類別', 6, 6, C3), ('整合：開源工具與中小企業指南', 6, 7, CG), ('整合：論文撰寫與投稿', 6, 7, CG)]
    rows = [[dict(t='工作項目', vm='r', rs=2), dict(t='第一年（2027.08–2028.07）', span=4), dict(t='第二年（2028.08–2029.07）', span=4)],
            [dict(t='', vm='c')] + q]
    for lab, a, b, col in G:
        rows.append([lab] + [dict(t='', fill=col if a <= i <= b else None) for i in range(8)])
    for lab, i in [('里程碑：預先註冊完成（2028.01.31）', 1), ('里程碑：期中報告（2028.07.31）', 3), ('里程碑：結案報告（2029.07.31）', 7)]:
        rows.append([dict(t=lab, b=True)] + [dict(t='◆' if k == i else '', c=True) for k in range(8)])
    rows.append([dict(t='註：Q1 為 8–10 月，Q2 為 11–1 月，Q3 為 2–4 月，Q4 為 5–7 月；色塊依階段區分，灰色為共同與整合工作。', span=9)])
    d.table('表 9　二年期工作項目與執行進度', [3638] + [750] * 8, rows, header=2, size=9.5, keep=True)

    d.h2('四、研究可能遭遇困難及解決途徑')
    d.p('在計畫提案階段即考量可能遭遇的困難及解決途徑，有助於降低執行風險，提高達成預期成果的機率。本計畫預劃之困難與解決途徑如下：')
    d.h5('1. 大型語言模型訪談與真人訪談不等效，或模型版本更替影響重現')
    d.p('解決途徑：(1) 保留研究 1a 的人工基準，若不等效，改採「機器人訪談＋人工覆核」的混合流程，並將不等效的樣態作為研究發現報告。(2) 訪談與編碼規則不綁定特定模型；記錄並公開模型版本、參數與提示詞，以開源權重模型保留可重現版本，並與商用模型平行比較。(3) 貢獻定位為以人工階梯訪談為基準的效度檢驗程序，而非首次使用大型語言模型，並於計畫開始時以預先註冊與預印本公開研究程序。')
    d.h5('2. 資料探勘找到假的族群差異')
    d.p('解決途徑：以預先註冊、發現／確認樣本切分與封存、安慰劑變數、置換檢定、拔靴穩定性與偽發現率控制為防線（表 8），只有在確認樣本中重現的族群才作結論；未重現的族群亦全數揭露。')
    d.h5('3. 無業界或平台合作，取不到實地資料；平台研究 API 條款改變')
    d.p('解決途徑：影片資料改用公開資料集或品牌官方帳號公開影片建立語料庫；社群資料以情境實驗為主、回憶調查為輔。影片特徵以節奏、剪輯頻率等抽象指標定義，不綁定特定平台或影片長度。')
    d.h5('4. 樣本規模、回收品質與成本不足')
    d.p('解決途徑：(1) 2028.02–2028.04 向 2–3 家樣本供應商詢價，設注意力檢核題與最短作答時間。(2) 經費不足時先縮減研究 3b 的複製品類，保留研究 3a 與 3c。(3) 各品類前測 3–4 個候選產品，選出享樂／實用知覺差異最大、喜好度相近者，避免操弄失敗。')
    d.h5('5. 計畫執行進度延誤')
    d.p('解決途徑：(1) 先完成核心研究（1b–1d、2b–2d、3a、3c、3d），1e、2a、3b 為延伸研究，必要時可移至後續計畫。(2) 制定彈性時間表並預留緩衝；每月檢視進度，採滾動式規劃。(3) 計畫開始（2027.08）與期中報告（2028.07）各更新一次文獻回顧與市場背景，跨境物流與退貨條件等操弄內容於前測時依市場實況校準。')
    d.h5('6. 研究倫理與個資')
    d.p('三個階段皆涉及人類受試者，將於計畫開始前取得人類研究倫理審查委員會（IRB）核准。受訪者經告知同意後參與，可隨時退出；逐字稿與側寫資料去識別化保存。大型語言模型訪談事先告知受訪者訪談者為 AI，傳送給模型的內容不含可識別個人資料，並採用不保留資料的 API 設定或本地部署模型。第三階段的好友暱稱僅在瀏覽器端用於呈現刺激，不回傳、不儲存；實驗使用虛構品牌與網紅帳號，結束後告知實驗目的。')

    # =====================================================================================
    d.h1('參、預期完成之工作項目及成果')
    d.h2('一、預期完成之工作項目及研究成果')
    d.p('本研究計畫「從經典研究方法提煉資料探勘——消費者異質性感知的數位行銷研究方法論」，分二年三階段進行：')
    d.item('（一）第一階段預期完成之工作項目：以計算化階梯法探索 AR 虛擬試穿的消費者價值內涵，完成人工與大型語言模型訪談的等效性檢驗、人機編碼一致性檢驗、關聯規則階梯價值圖，以及跨品類價值族群與其預測效度。此階段聚焦於認知與價值層面。', ind=960)
    d.item('（二）第二階段預期完成之工作項目：以影片探勘與跨品類實驗檢驗短影音視聽一致性的因果效果，並以因果森林描繪異質處理效果地圖，提出短影音製作指南。此階段聚焦於心理處理歷程與觀看行為。', ind=960)
    d.item('（三）第三階段預期完成之工作項目：以情境實驗與回憶調查建構社群商務的異質性路徑模型，驗證前兩階段的族群，並提出銷售轉換建議。此階段聚焦於不同情境與族群下，心理與行為的相互影響。', ind=960)
    d.p('本計畫將於第二年綜整三階段的結果，以不同的方法與觀點比較、整合和詮釋消費者異質性，並將分析程序整合為開源工具包。預期成果與完成時間如表 10。')
    d.table('表 10　預期成果與績效指標',
            [6238, 1500, 1900],
            [['成果', '數量', '完成時間'],
             ['預先註冊文件（每階段 1 份）', dict(t='3 份', c=True), dict(t='2028.01', c=True)],
             ['計算化階梯法工具（訪談機器人、編碼簿、關聯規則階梯價值圖程式）', dict(t='1 套', c=True), dict(t='2028.07', c=True)],
             ['跨品類階梯價值圖與價值族群報告', dict(t='1 份', c=True), dict(t='2028.07', c=True)],
             ['短影音影片特徵語料庫與擷取程式', dict(t='1 套', c=True), dict(t='2028.10', c=True)],
             ['短影音異質處理效果地圖與製作指南', dict(t='1 份', c=True), dict(t='2029.04', c=True)],
             ['社群商務異質性路徑模型與銷售轉換建議', dict(t='1 份', c=True), dict(t='2029.07', c=True)],
             ['開源工具包與中小企業使用指南；個資與演算法公平研究指引', dict(t='各 1', c=True), dict(t='2029.07', c=True)],
             ['公開資料集（去識別化）', dict(t='3 份', c=True), dict(t='2029.07', c=True)],
             ['國際研討會論文', dict(t='3 篇', c=True), dict(t='2028.08–2029.07', c=True)],
             ['頂級期刊投稿（JMR／IJRM；JM／JMR／JCR；JAMS／ISR／MISQ）', dict(t='3 篇', c=True), dict(t='2029.07', c=True)],
             ['培育碩博士研究助理（含資料科學訓練）', dict(t='3–4 名', c=True), dict(t='計畫全期', c=True)]])

    d.p('本研究計畫透過多階段研究設計，系統性探討消費者在三種前沿數位互動情境中的異質性，提出一套兼具理論深度與實務意涵的分析架構。研究結果不僅為經典研究方法與資料探勘的整合提供實證基礎，也為品牌與中小企業在進行消費者分群、內容測試與社群行銷時，提供具體可行的方向與工具，進一步拓展數位行銷研究方法的廣度與深度。')
    d.h2('二、對於參與之工作人員，預期可獲之訓練')
    d.h3('(一) 對於計畫主持人而言，可整合經典研究方法與資料探勘，並延伸至數位行銷、消費者心理與資訊科學的跨領域研究。')
    d.p('計畫主持人的學術專長在於電子商務與數位行銷中的消費者行為研究，有助於研究架構與假設之建構，以及訪談、實驗與問卷之設計。透過本計畫的執行，計畫主持人將更深入鑽研大型語言模型、因果機器學習與異質性 SEM 在行銷研究中的應用，並以二年三階段的系統觀點，詮釋消費者在前沿互動情境中的心理與行為。')
    d.h3('(二) 對於參與之研究助理而言，除了學習數位行銷之相關知識，亦可熟悉質化與量化研究方法及資料科學工具。')
    d.p('研究助理將參與文獻蒐集、階梯訪談、編碼、實驗刺激物製作與資料蒐集，並接受 R 與 Python 的資料分析訓練，包括關聯規則、因果森林與 SEM 決策樹；同時學習預先註冊、開放資料與程式碼公開等開放科學實務，以備將來獨立或共同研究之能力。')

    d.h2('三、對學術研究、國家發展及其他預期貢獻')
    d.h3('（一）學術研究績效')
    d.p('本計畫結合經典研究方法、資料探勘與消費者心理三個面向，以多階段與多方法的方式，歷經價值發現、因果檢驗與模型推廣三個階段，三個階段各自形成可投稿頂級期刊的方法與理論貢獻：第一階段提出並驗證以人工訪談為基準、不綁定特定模型的計算化階梯法（目標期刊 JMR 或 IJRM）；第二階段將跨感官一致性從「平均是否有效」推進到「對誰有效、在哪些品類有效」（目標期刊 JM、JMR 或 JCR）；第三階段揭示跨境不確定性如何放大社群關係的信任價值，並將關係強度理論從「事先指定的調節變數」推進到「資料決定的邊界條件」（目標期刊 JAMS、ISR 或 MISQ）。研究程序、程式碼與去識別化資料將公開，使本計畫得以延展為長期且具累積性的研究脈絡。')
    d.h3('（二）實務應用與國家發展績效')
    d.p('本計畫的開源工具包可讓資源受限的中小企業以低成本進行消費者分群與內容測試，回應主題五的電商市場發展需求 (Wang & Zhang, 2025)。研究成果可協助品牌判斷 AR 試穿、短影音與社群推薦的投放對象，降低無效投放與退貨成本；以降低退貨減少逆向物流的碳足跡，具有永續效益。此外，本計畫建立的個資與演算法公平指引，可作為以消費者特徵進行定向行銷時的倫理參考，促進資料驅動行銷的負責任應用 (Martin & Murphy, 2017)。')

    # =====================================================================================
    d.h1('肆、參考文獻')
    d.references([r for r in refs if r.used])
